import React, {useEffect, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter, NavLink, Routes, Route, useNavigate, useLocation} from 'react-router-dom';
import axios from 'axios';
import {LayoutDashboard, FileCheck2, Files, Search, History, GitBranch, Fingerprint, ScrollText, Settings, ShieldCheck, Bell, ChevronDown, Globe, UploadCloud, FileText, CheckCircle2, AlertTriangle, Clock3, CircleHelp, ArrowUpRight, ArrowRight, Menu, X, Download, SearchCheck, Plus, Activity, Landmark, LogOut, Eye, Database, LockKeyhole} from 'lucide-react';
import {ResponsiveContainer, BarChart, Bar, XAxis, Tooltip, PieChart, Pie, Cell} from 'recharts';
import './styles.css';
import './brand-overrides.css';
import {recognizeDeedImage, parseDeedOcr} from './ocr.js';

const API = import.meta.env.VITE_API_URL || `${window.location.protocol}//${window.location.hostname}:8000/api/v1`;
const http = axios.create({baseURL:API});
http.interceptors.request.use(async c=>{
 if(c.url==='/verifications'&&c.data instanceof FormData){
  const file=c.data.get('file');
  if(file instanceof Blob&&/^image\/(jpeg|png)$/.test(file.type)){
   const ocr=await recognizeDeedImage(file);
   const extracted=parseDeedOcr(ocr.text);
   const existing=JSON.parse(c.data.get('fields_json')||'{}');
   c.data.set('fields_json',JSON.stringify({...extracted,deed_type:extracted.deed_type||existing.deed_type||'Sale'}));
   c.data.set('ocr_text',ocr.text.slice(0,12000));
   c.data.set('ocr_confidence',String(ocr.confidence??''));
  }
 }
 return c;
});
http.interceptors.request.use(c=>{const t=localStorage.getItem('lg_token');if(t)c.headers.Authorization=`Bearer ${t}`;return c;});
